    nodes = []
    for node in diagram.nodes:
        if node.container:
            continue
        stereotype = stereotypes.get(node.id)
        if node.shape == "start":
            kind = "initial"
        elif node.shape == "end":
            kind = "final"
        elif stereotype == "choice":
            kind = "choice"
        elif stereotype in ("fork", "join"):
